<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { knowledgeApi, type EvidenceContributions } from '../knowledgeApi'
type Candidate = { cpe: string; identification_basis: string; basis_verification: string; provenance: Record<string, unknown> }
type Result = { inventory_state: string; policy_state: string | null; proposal: { algorithm_version: string; content_digest: string; catalog_content_digest: string; rules_content_digest: string; requested_purl: string | null; resolved_purl: string | null; candidates: Candidate[]; rejected_candidates: unknown[]; reviewed_rules: unknown[]; limitations: string[] } }
const props = defineProps<{ project: string; state: string; componentRef: string; records?: EvidenceContributions['cpe'] }>()
const result = ref<Result | null>(null), busy = ref(false), error = ref('')
const groups = computed(() => [{ label: 'Declared by sources', entries: props.records?.declared || [] }, { label: 'Configured mappings', entries: props.records?.curated || [] }, { label: 'Accepted identities', entries: props.records?.accepted || [] }, { label: 'Discovery candidates', entries: props.records?.candidates || [] }])
const label = (value: string) => value.replaceAll('_', ' ')
let sequence = 0
async function load() {
  if (busy.value || !props.componentRef) return
  const request = ++sequence, pin = props.state
  busy.value = true; error.value = ''
  try { const data = await knowledgeApi<Result>(`/projects/${encodeURIComponent(props.project)}/states/${encodeURIComponent(pin)}/cpe?${new URLSearchParams({ component_ref: props.componentRef })}`); if (request !== sequence) return; if (data.inventory_state !== pin) throw new Error('CPE response differs from the requested inventory state.'); result.value = data }
  catch (err) { if (request === sequence) error.value = err instanceof Error ? err.message : 'CPE discovery unavailable' }
  finally { if (request === sequence) busy.value = false }
}
function download() { if (!result.value) return; const url = URL.createObjectURL(new Blob([JSON.stringify(result.value, null, 2)], { type: 'application/json' })), link = document.createElement('a'); link.href = url; link.download = 'dtvp-cpe-candidates.json'; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
watch(() => [props.project, props.state, props.componentRef], () => { ++sequence; result.value = null; busy.value = false; error.value = '' })
onBeforeUnmount(() => { ++sequence })
</script>
<template><details class="knowledge-cpe-identification" aria-label="CPE identification"><summary>CPE identification <span v-if="records">· {{ records.declared.length }} declared · {{ records.accepted.length }} accepted · {{ records.candidates.length }} candidates</span></summary><p v-if="records" class="hint">Configured mappings and candidates use the current project discovery policy. They remain distinct from source declarations and accepted identity.</p><div v-if="records" class="cpe-groups"><section v-for="group in groups" :key="group.label"><h4>{{ group.label }}</h4><p v-if="!group.entries.length" class="hint">None recorded</p><details v-for="entry in group.entries" :key="entry.id"><summary>{{ entry.summary || entry.label }}</summary><small>{{ entry.label }} · {{ label(entry.status) }}</small><code v-if="typeof entry.claims.cpe === 'string'">{{ entry.claims.cpe }}</code><pre>{{ JSON.stringify({ claims: entry.claims, provenance: entry.provenance, diagnostics: entry.diagnostics }, null, 2) }}</pre></details></section></div><p v-else class="hint">CPE contribution summary unavailable; discover candidates explicitly for this component.</p><details v-if="records?.diagnostics.length"><summary>Identity limitations</summary><ul><li v-for="item in records.diagnostics" :key="item">{{ label(item) }}</li></ul></details><details><summary>CPE candidate discovery</summary><p class="hint">Inspect current discovery-policy candidates against this pinned inventory. Candidates and configured mappings do not establish accepted identity or vulnerability applicability.</p><button :disabled="busy || !componentRef" @click="load">{{ busy ? 'Loading candidates…' : result ? 'Refresh CPE candidates' : 'Load CPE candidates' }}</button><p v-if="error" role="alert">{{ error }}</p><template v-if="result"><p v-if="!result.proposal.candidates.length">No candidates from these inputs; a matching identity may still exist.</p><article v-for="(candidate, index) in result.proposal.candidates" :key="index"><code>{{ candidate.cpe }}</code><small>{{ label(candidate.identification_basis) }} · {{ label(candidate.basis_verification) }}</small><details><summary>Candidate attribution</summary><pre>{{ JSON.stringify(candidate.provenance, null, 2) }}</pre></details></article><ul><li v-for="item in result.proposal.limitations" :key="item">{{ item }}</li></ul><details><summary>CPE input and policy pins</summary><pre>{{ JSON.stringify(result, null, 2) }}</pre></details><button @click="download">Download CPE candidate JSON</button></template></details></details></template>
<style scoped>.knowledge-cpe-identification{border-top:1px solid var(--line);padding:7px 0;font-size:.78rem}.knowledge-cpe-identification>summary{font-size:.8rem}.knowledge-cpe-identification>summary span{font-weight:400;color:var(--muted);font-size:.72rem}.cpe-groups{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.cpe-groups h4{margin:5px 0;font-size:.75rem}.cpe-groups details{margin:4px 0}.cpe-groups summary{font-size:.73rem;overflow-wrap:anywhere}pre,code{font-size:.7rem;white-space:pre-wrap;overflow-wrap:anywhere}code{display:block}.hint{font-size:.73rem;color:var(--muted);margin:4px 0}article{margin:8px 0}pre{max-height:30vh;overflow:auto}@media(max-width:550px){.cpe-groups{grid-template-columns:1fr}}
</style>
